// src/Component/userSlice.js
import { createSlice, createAsyncThunk, createSelector } from "@reduxjs/toolkit";
import axios from "axios";

// Django backend URL
const API_URL = "http://127.0.0.1:8000/api/users/";

// --- Thunks (API calls) ---
// Get token from localStorage
const getTokenHeader = () => {
  const token = localStorage.getItem("token");
  return { Authorization: `Bearer ${token}` };
};

// Fetch all users
export const fetchUsersAsync = createAsyncThunk("users/fetchAll", async () => {
  const res = await axios.get(API_URL, { headers: getTokenHeader() });
  return res.data.map(user => ({
    ...user,
    profile: user.profile || { bio: "", phone: "" },
  }));
});

// Add new user
export const addUserAsync = createAsyncThunk("users/add", async (user) => {
  const res = await axios.post(API_URL, user, { headers: getTokenHeader() });
  return { ...res.data, profile: res.data.profile || { bio: "", phone: "" } };
});

// Update user
export const updateUserAsync = createAsyncThunk("users/update", async (user) => {
  const res = await axios.put(`${API_URL}${user.id}/`, user, { headers: getTokenHeader() });
  return { ...res.data, profile: res.data.profile || { bio: "", phone: "" } };
});

// Delete user
export const deleteUserAsync = createAsyncThunk("users/delete", async (id) => {
  await axios.delete(`${API_URL}${id}/`, { headers: getTokenHeader() });
  return id;
});

// --- State ---
const initialState = {
  users: [],
  searchTerm: "",
  viewUserData: null,
  isEditMode: false,
  loading: false,
  error: null,
};

// --- Slice ---
const usersSlice = createSlice({
  name: "users",
  initialState,
  reducers: {
    setSearchTerm(state, action) { state.searchTerm = action.payload; },
    openAddUser(state) {
      state.viewUserData = { id: null, username: "", email: "", role: "", status: "Active", profile: { bio: "", phone: "" } };
      state.isEditMode = true;
    },
    openViewUser(state, action) {
      const id = action.payload;
      const user = state.users.find((u) => u.id === id);
      state.viewUserData = user ? { ...user } : null;
      state.isEditMode = false;
    },
    startEdit(state) { state.isEditMode = true; },
    closeModal(state) { state.viewUserData = null; state.isEditMode = false; },
    changeField(state, action) {
      const { key, value } = action.payload;
      if (state.viewUserData) {
        if (state.viewUserData.profile && key in state.viewUserData.profile) {
          state.viewUserData.profile[key] = value;
        } else {
          state.viewUserData[key] = value;
        }
      }
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchUsersAsync.pending, (state) => { state.loading = true; state.error = null; })
      .addCase(fetchUsersAsync.fulfilled, (state, action) => { state.loading = false; state.users = action.payload || []; })
      .addCase(fetchUsersAsync.rejected, (state, action) => { state.loading = false; state.error = action.error.message || "Failed to fetch users"; })
      .addCase(addUserAsync.fulfilled, (state, action) => { state.users.push(action.payload); })
      .addCase(updateUserAsync.fulfilled, (state, action) => {
        const updated = action.payload;
        const i = state.users.findIndex((u) => u.id === updated.id);
        if (i !== -1) state.users[i] = updated;
      })
      .addCase(deleteUserAsync.fulfilled, (state, action) => { state.users = state.users.filter((u) => u.id !== action.payload); });
  },
});

export const { setSearchTerm, openAddUser, openViewUser, startEdit, closeModal, changeField } = usersSlice.actions;
export const selectUsersState = (state) => state.users;
export const selectFilteredUsers = createSelector(
  [selectUsersState],
  (s) => s.users.filter((u) => (u.username || "").toLowerCase().includes((s.searchTerm || "").toLowerCase()))
);

export default usersSlice.reducer;
